changeSet.sql:
CREATE TABLE order_service.order_stream_heads ( aggregate_id UUID PRIMARY KEY, current_version BIGINT NOT NULL DEFAULT 0, last_event_id UUID, last_hash VARCHAR(64) NOT NULL DEFAULT repeat('0', 64), updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_order_stream_version_non_negative CHECK (current_version >= 0) );
CREATE TABLE order_service.order_event_store ( global_position BIGSERIAL PRIMARY KEY, event_id UUID NOT NULL, aggregate_id UUID NOT NULL, aggregate_type VARCHAR(50) NOT NULL, aggregate_version BIGINT NOT NULL, event_type VARCHAR(100) NOT NULL, payload JSONB NOT NULL, payload_canonical TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, metadata_canonical TEXT NOT NULL, schema_version INTEGER NOT NULL, occurred_at TIMESTAMP NOT NULL, prev_hash VARCHAR(64) NOT NULL, hash VARCHAR(64) NOT NULL, CONSTRAINT uk_order_event_id UNIQUE (event_id), CONSTRAINT uk_order_aggregate_version UNIQUE (aggregate_id, aggregate_version), CONSTRAINT fk_order_event_stream FOREIGN KEY (aggregate_id) REFERENCES order_service.order_stream_heads(aggregate_id), CONSTRAINT ck_order_event_version_positive CHECK (aggregate_version > 0), CONSTRAINT ck_order_event_schema_version_positive CHECK (schema_version > 0) );
CREATE INDEX idx_order_event_stream ON order_service.order_event_store(aggregate_id, aggregate_version); CREATE INDEX idx_order_event_type_position ON order_service.order_event_store(event_type, global_position); CREATE INDEX idx_order_event_occurred_at ON order_service.order_event_store(occurred_at);

CREATE TABLE order_service.orders_current ( order_id UUID PRIMARY KEY, user_id UUID NOT NULL, market_id VARCHAR(50) NOT NULL, market_sequence BIGINT NOT NULL, side VARCHAR(4) NOT NULL, price INTEGER NOT NULL, original_amount INTEGER NOT NULL, remaining_amount INTEGER NOT NULL, matched_amount INTEGER NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL, aggregate_version BIGINT NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT ck_orders_current_side CHECK (side IN ('BUY', 'SELL')), CONSTRAINT ck_orders_current_amounts CHECK ( original_amount >= 0 AND remaining_amount >= 0 AND matched_amount >= 0 ), CONSTRAINT ck_orders_current_version_positive CHECK (aggregate_version > 0) );
CREATE INDEX idx_orders_current_user_status ON order_service.orders_current(user_id, status); CREATE INDEX idx_orders_current_market_sequence ON order_service.orders_current(market_id, market_sequence);
CREATE TABLE order_service.projection_checkpoints ( projection_name VARCHAR(100) PRIMARY KEY, last_global_position BIGINT NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_projection_position_non_negative CHECK (last_global_position >= 0) );

ALTER TABLE order_service.order_stream_heads
ADD CONSTRAINT ck_order_stream_remaining_non_negative
CHECK (remaining_amount IS NULL OR remaining_amount >= 0);

ALTER TABLE order_service.order_event_store
    ALTER COLUMN metadata DROP DEFAULT;

ALTER TABLE order_service.order_event_store
    ALTER COLUMN payload TYPE TEXT USING payload::text;

ALTER TABLE order_service.order_event_store
    ALTER COLUMN metadata TYPE TEXT USING metadata::text;

ALTER TABLE order_service.order_event_store
    ALTER COLUMN metadata SET DEFAULT '{}';

ALTER TABLE order_service.order_event_outbox
DROP CONSTRAINT IF EXISTS ck_order_outbox_status;

ALTER TABLE order_service.order_event_outbox
ADD CONSTRAINT ck_order_outbox_status
    CHECK (status IN ('PENDING', 'IN_FLIGHT', 'SENT', 'FAILED'));

CREATE INDEX IF NOT EXISTS idx_order_outbox_in_flight_timeout
    ON order_service.order_event_outbox(updated_at)
    WHERE status = 'IN_FLIGHT';

ALTER TABLE order_service.order_trade_execution_inbox
    DROP CONSTRAINT IF EXISTS ck_order_trade_execution_inbox_status;
ALTER TABLE order_service.order_trade_execution_inbox
    ADD CONSTRAINT ck_order_trade_execution_inbox_status
    CHECK (status IN ('RECEIVED', 'APPLIED', 'PENDING_PREREQUISITE', 'FAILED_RETRYABLE'));

ALTER TABLE order_service.order_event_store
DROP CONSTRAINT IF EXISTS fk_order_event_stream;

CREATE TABLE IF NOT EXISTS order_service.order_event_store_relay_checkpoints (
    relay_name VARCHAR(100) PRIMARY KEY,
    last_global_position BIGINT NOT NULL DEFAULT 0,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_order_event_store_relay_checkpoint_position
        CHECK (last_global_position >= 0)
);

ALTER TABLE order_service.order_trade_execution_inbox
    ADD COLUMN IF NOT EXISTS next_retry_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ADD COLUMN IF NOT EXISTS claimed_by VARCHAR(80),
    ADD COLUMN IF NOT EXISTS claim_until TIMESTAMP;

ALTER TABLE order_service.order_trade_execution_inbox
    DROP CONSTRAINT IF EXISTS ck_order_trade_execution_inbox_status;
ALTER TABLE order_service.order_trade_execution_inbox
    ADD CONSTRAINT ck_order_trade_execution_inbox_status
    CHECK (status IN ('RECEIVED', 'APPLIED', 'PENDING_PREREQUISITE',
                      'FAILED_RETRYABLE', 'IN_PROGRESS', 'FAILED_PERMANENT'));

CREATE INDEX IF NOT EXISTS idx_order_trade_execution_inbox_retry
    ON order_service.order_trade_execution_inbox(status, next_retry_at, updated_at)
    WHERE status IN ('PENDING_PREREQUISITE', 'FAILED_RETRYABLE', 'IN_PROGRESS');
